$('#googleAccount').onclick=async()=>{if(accountChangeBlocked())return;const button=$('#googleAccount');try{button.disabled=true;setAccountNotice('');let result;const current=await ensureAuth();if(current.isAnonymous){try{result=await linkWithPopup(current,googleProvider)}catch(e){const credential=GoogleAuthProvider.credentialFromError(e);if(!credential||!['auth/credential-already-in-use','auth/email-already-in-use'].includes(e.code))throw e;await signOut(auth);authPromise=null;result=await signInWithCredential(auth,credential)}}else result=await signInWithPopup(auth,googleProvider);await saveAccountProfile(result.user);show('account')}catch(e){setAccountNotice(accountMessage(e))}finally{button.disabled=false}};
$('#signupForm').onsubmit=async e=>{e.preventDefault();if(accountChangeBlocked())return;const button=e.currentTarget.querySelector('button[type="submit"]');try{button.disabled=true;setAccountNotice('');const current=await ensureAuth(),credential=EmailAuthProvider.credential($('#signupEmail').value.trim(),$('#signupPassword').value);let result;if(current.isAnonymous)result=await linkWithCredential(current,credential);else throw Error('You are already signed in.');await updateProfile(result.user,{displayName:$('#signupName').value.trim()});await saveAccountProfile(result.user);renderAccount(result.user)}catch(err){setAccountNotice(accountMessage(err))}finally{button.disabled=false}};
$('#signinForm').onsubmit=async e=>{e.preventDefault();if(accountChangeBlocked())return;const button=e.currentTarget.querySelector('button[type="submit"]'),email=$('#signinEmail').value.trim(),password=$('#signinPassword').value;try{button.disabled=true;setAccountNotice('');if(auth.currentUser?.isAnonymous){await signOut(auth);authPromise=null}const result=await signInWithEmailAndPassword(auth,email,password);await saveAccountProfile(result.user)}catch(err){setAccountNotice(accountMessage(err));await ensureAuth().catch(()=>{})}finally{button.disabled=false}};
$('#resetPassword').onclick=async()=>{const email=$('#signinEmail').value.trim();if(!email)return setAccountNotice('Enter your email address first.');try{await sendPasswordResetEmail(auth,email);setAccountNotice('Password reset email sent.',true)}catch(e){setAccountNotice(accountMessage(e))}};
$('#signOutAccount').onclick=async()=>{if(accountChangeBlocked())return;await signOut(auth);authPromise=null;await ensureAuth();navigate('home')};
function accountMessage(e){const messages={'auth/email-already-in-use':'That email already has an account. Choose Sign in instead.','auth/invalid-credential':'Incorrect email or password.','auth/weak-password':'Use a password with at least six characters.','auth/popup-closed-by-user':'The sign-in window was closed.','auth/popup-blocked':'Your browser blocked the sign-in window. Allow pop-ups and try again.','auth/unauthorized-domain':'Add this GitHub Pages domain under Firebase Authentication → Settings → Authorized domains.','auth/operation-not-allowed':'Enable this sign-in method in Firebase Authentication.'};return messages[e.code]||e.message||'Account request failed.'}
function clearOnlineListeners(){onlineUnsubs.forEach(x=>x());onlineUnsubs=[]}
function hydrateState(value){value.bids??={};value.bidStatus??=[];value.players??=[];value.players.forEach(p=>p.picks??=[]);if(value.auction)value.auction.passed??=[];return value}
function publicGameState(source){const copy=structuredClone(source);copy.bidStatus=Object.keys(source.bids||{});copy.bids={};return copy}
async function watchActiveCount(){try{await ensureAuth();onValue(ref(db,'publicGames'),snap=>{const games=Object.values(snap.val()||{}).filter(g=>g.state?.phase!=='finished'&&Date.now()-(g.updatedAt||0)<86400000);$('#activeCount').textContent=games.length},()=>{$('#activeCount').textContent='—'})}catch{$('#activeCount').textContent='—'}}
watchActiveCount();
$('#createRoom').onclick=async()=>{
  const button=$('#createRoom'),name=$('#hostName').value.trim()||'Host',c=config($('#hostForm .setup'));c.visibility=$('#roomVisibility').value;c.spectators=$('#spectatorAccess').value;
  try{button.disabled=true;button.textContent='Creating room…';validate(c,[name,'guest']);const [items,user]=await Promise.all([getItems(c),ensureAuth()]);let code;
    do{code=makeCode()}while((await get(ref(db,roomPath(code)))).exists());
    role='host';myId=user.uid;onlineHostUid=myId;currentRoomCode=code;state=fresh(gameConfig(c),[name],items);state.players[0].id=myId;state.players[0].avatar=currentAccountData?.account?.avatar||'';state.phase='lobby';history.replaceState({},'',urlFor('join',code));
    const roomRef=ref(db,roomPath(code)),publicRef=ref(db,`publicGames/${code}`);await set(roomRef,{hostUid:myId,createdAt:serverTimestamp(),state});await set(ref(db,roomPath(code,`members/${myId}`)),true);await set(ref(db,roomPath(code,`presence/${myId}`)),{online:true});await onDisconnect(ref(db,roomPath(code,`presence/${myId}`))).remove();if(c.visibility==='public')try{await set(publicRef,{hostUid:myId,updatedAt:serverTimestamp(),state:publicGameState(state)})}catch{console.info('Public game directory is unavailable until the updated Firebase rules are published.')}saveOnlineSession('host',code,name);attachHost(code);attachRoomSocial(code);if(pendingChallengeTarget){await set(ref(db,`gameInvites/${pendingChallengeTarget}/${myId}`),{fromUid:myId,fromName:name,room:code,createdAt:serverTimestamp()}).catch(()=>{});pendingChallengeTarget=null}renderLobby();
  }catch(e){alert(firebaseMessage(e));button.disabled=false;button.textContent='Create room'}
};
function attachHost(code){clearOnlineListeners();
  onlineUnsubs.push(onChildAdded(ref(db,roomPath(code,'joinRequests')),async snap=>{const id=snap.key,request=snap.val();if(!state.players.some(p=>p.id===id)&&state.phase==='lobby'&&state.players.length<8){state.players.push({id,name:String(request.name||'Player').slice(0,20),avatar:String(request.avatar||'').slice(0,4),budget:state.config.budget,picks:[],connected:true});await broadcast();renderLobby()}await remove(snap.ref)}));
  onlineUnsubs.push(onChildAdded(ref(db,roomPath(code,'actions')),async snap=>{const action=snap.val();if(state.phase==='playing')applyAction(snap.key,action.action,action.value);await remove(snap.ref)}));
  onlineUnsubs.push(onValue(ref(db,roomPath(code,'presence')),snap=>{if(!state)return;let changed=false;for(const p of state.players){if(p.id===myId)continue;const online=snap.child(p.id).exists();if(p.connected!==online){p.connected=online;changed=true;if(!online&&state.phase==='playing'&&state.config.bidMode==='open'&&state.auction&&!state.auction.passed.includes(p.id)){state.auction.passed.push(p.id);advanceAuction()}}}if(changed){broadcast();state.phase==='lobby'?renderLobby():render()}}));
}
$('#joinRoom').onclick=async()=>{
  const code=$('#joinCode').value.trim().toUpperCase(),name=$('#joinName').value.trim(),button=$('#joinRoom');
  if(code.length!==6||!name)return $('#joinError').textContent='Enter your name and six-character room code.';
  try{button.disabled=true;button.textContent='Joining…';$('#joinError').textContent='';const user=await ensureAuth(),roomRef=ref(db,roomPath(code)),snapshot=await get(roomRef);if(!snapshot.exists())throw Error('Room not found or host is offline.');const room=snapshot.val();if(Date.now()-(room.createdAt||0)>86400000)throw Error('This room has expired.');if(room.state?.phase!=='lobby')throw Error('This game has already started.');if((room.state?.players?.length||0)>=8)throw Error('Room is full.');
    role='guest';myId=user.uid;onlineHostUid=room.hostUid;currentRoomCode=code;history.replaceState({},'',urlFor('join',code));await set(ref(db,roomPath(code,`members/${myId}`)),true);await set(ref(db,roomPath(code,`presence/${myId}`)),{online:true});await onDisconnect(ref(db,roomPath(code,`presence/${myId}`))).remove();await set(ref(db,roomPath(code,`joinRequests/${myId}`)),{name:name.slice(0,20),avatar:currentAccountData?.account?.avatar||'',joinedAt:serverTimestamp()});saveOnlineSession('guest',code,name);
    clearOnlineListeners();onlineUnsubs.push(onValue(ref(db,roomPath(code,'state')),snap=>{if(!snap.exists()){show('join');$('#joinError').textContent='The host closed this room.';return}state=hydrateState(snap.val());if(!state.players.some(p=>p.id===myId))return;state.phase==='lobby'?renderLobby():render()}));watchHostMigration(code,onlineHostUid);attachRoomSocial(code);
  }catch(e){$('#joinError').textContent=firebaseMessage(e);button.disabled=false;button.textContent='Join room'}
};
function firebaseMessage(e){if(e.message?.includes('Room')||e.message?.includes('room')||e.message?.includes('game'))return e.message;if(e.code==='auth/admin-restricted-operation')return'Anonymous sign-in is not enabled in Firebase Authentication.';if(e.code==='PERMISSION_DENIED'||e.code==='permission-denied')return'Firebase blocked the request. Publish the included database rules.';return'Could not connect to Firebase. '+(e.message||'Check your connection.')}
async function broadcast(){if(role==='host'&&currentRoomCode){const publicState=publicGameState(state);await set(ref(db,roomPath(currentRoomCode,'state')),publicState);if(state.config?.visibility==='public')update(ref(db,`publicGames/${currentRoomCode}`),{hostUid:myId,updatedAt:serverTimestamp(),state:publicState}).catch(()=>{});else remove(ref(db,`publicGames/${currentRoomCode}`)).catch(()=>{})}}
async function loadLiveGames(){show('spectate');$('#liveGames').innerHTML='<p class="muted">Loading active games…</p>';try{await ensureAuth();if(liveDirectoryUnsub)liveDirectoryUnsub();liveDirectoryUnsub=onValue(ref(db,'publicGames'),snap=>{const games=Object.entries(snap.val()||{}).filter(([,g])=>g.state?.phase!=='finished'&&g.state?.config?.spectators!=='off'&&Date.now()-(g.updatedAt||0)<86400000).sort((a,b)=>(b[1].updatedAt||0)-(a[1].updatedAt||0));$('#liveGames').innerHTML=games.length?games.map(([code,g])=>{const s=hydrateState(g.state),item=s.items?.[s.round];return`<article class="live-card"><div><span class="live-dot">LIVE</span><h3>Room ${esc(code)}</h3><p>${s.players.length} players · ${s.config?.bidMode==='open'?'Open Auction':'Blind Bid'} · ${s.phase==='lobby'?'Lobby':`Round ${s.round+1} of ${s.config?.rounds}`}</p>${item?`<small>Now drafting: ${esc(item.name)}</small>`:''}</div><button class="watchGame" data-room="${esc(code)}">Watch →</button></article>`}).join(''):'<div class="empty-live"><h3>No active games</h3><p class="muted">Create a room and it will appear here.</p></div>';$$('.watchGame',$('#liveGames')).forEach(b=>b.onclick=()=>watchGame(b.dataset.room))},()=>{$('#liveGames').innerHTML='<p class="error">Live games need the updated Firebase rules included with this build.</p>'})}catch(e){$('#liveGames').innerHTML=`<p class="error">${esc(firebaseMessage(e))}</p>`}}
async function watchGame(code,push=true){if(push)history.pushState({},'',urlFor('spectate',code));show('spectatorGame');$('#spectatorContent').innerHTML='<section class="card"><p class="muted">Connecting to live game…</p></section>';try{await ensureAuth();if(spectatorUnsub)spectatorUnsub();spectatorUnsub=onValue(ref(db,`publicGames/${code}`),snap=>{if(!snap.exists())return $('#spectatorContent').innerHTML='<section class="card"><h2>Game unavailable</h2><p>This room has ended or the host went offline.</p></section>';if(snap.val().state?.config?.spectators==='off')return $('#spectatorContent').innerHTML='<section class="card"><h2>Spectators are off</h2><p>The host made this game private to its players.</p></section>';renderSpectator(code,hydrateState(snap.val().state),snap.val().votes||{})},()=>{$('#spectatorContent').innerHTML='<section class="card"><p class="error">Spectating needs the updated Firebase rules.</p></section>'})}catch(e){$('#spectatorContent').innerHTML=`<section class="card"><p class="error">${esc(firebaseMessage(e))}</p></section>`}}
function renderSpectator(code,s,votes={}){const item=s.items?.[s.round],submitted=new Set(s.bidStatus||[]),waiting=s.players.filter(p=>p.connected!==false&&!submitted.has(p.id));let status='';if(s.phase==='lobby')status='<p class="spectator-callout">Waiting for the host to start.</p>';else if(s.phase==='finished')status='<p class="spectator-callout">Draft complete.</p>';else if(s.result){const winner=s.players.find(p=>p.id===s.result.winner);status=`<p class="spectator-callout">${winner?`${esc(winner.name)} won for $${s.result.amount}`:'No winner this round'}</p>`}else if(s.config?.bidMode==='open'){const high=s.players.find(p=>p.id===s.auction?.highBidder),turn=s.players.find(p=>p.id===s.auction?.turn);status=`<div class="spectator-auction"><span>High bid <b>$${s.auction?.highBid||0}</b>${high?` by ${esc(high.name)}`:''}</span><span>Playing now <b>${esc(turn?.name||'—')}</b></span></div>`}else status=`<p class="spectator-callout">Waiting for: <b>${waiting.length?waiting.map(p=>esc(p.name)).join(', '):'Reveal'}</b></p>`;$('#spectatorContent').innerHTML=`<section class="spectator-hero"><p class="eyebrow">SPECTATING · ROOM ${esc(code)}</p><small>${s.phase==='playing'?`Round ${s.round+1} of ${s.config?.rounds}`:s.phase}</small><h2>${esc(item?.name||'Waiting in lobby')}</h2><p>${esc(item?.sub||'')}</p>${item?.preview?`<audio class="preview" controls preload="none" src="${esc(item.preview)}"></audio>`:''}</section>${status}<div class="spectator-players">${s.players.map(p=>`<article><b>${esc(p.name)}</b><span>$${p.budget} left · ${(p.picks||[]).length} picks</span><small>${p.connected===false?'Offline':s.config?.bidMode==='blind'&&s.phase==='playing'&&!s.result?(submitted.has(p.id)?'Bid locked':'Choosing bid'):s.auction?.passed?.includes(p.id)?'Passed':'Active'}</small></article>`).join('')}</div>`;if(s.phase==='finished'&&s.config?.spectators!=='off')renderAudienceVoting(code,s,votes)}
function renderLobby(){show('lobby');$('#roomCode').textContent=currentRoomCode||'…';$('#inviteLink').value=inviteUrl(currentRoomCode);$('#connectionStatus').textContent=role==='host'?'Share the link or room code. Keep this tab open.':'Connected through Firebase — waiting for the host.';$('#lobbySettings').innerHTML=`<p><b>${state.config.bidMode==='open'?'Open Auction':'Blind Bid'}</b> · $${state.config.budget} budget · ${state.config.rounds} rounds</p>`;$('#lobbyPlayers').innerHTML=state.players.map(p=>`<span class="pill">${p.avatar?`${esc(p.avatar)} `:''}${esc(p.name)}</span>`).join('');$('#startOnline').classList.toggle('hidden',role!=='host');$('#startOnline').disabled=state.players.length<2;$('#lobbyHint').textContent=state.players.length<2?'Waiting for at least one more player…':''}
$('#startOnline').onclick=()=>{if(role==='host'&&state.players.length>=2){state.phase='playing';beginRound();broadcast();render()}};
function beginRound(){state.bids={};state.bidStatus=[];state.result=null;state.localIndex=0;state.localStep='handoff';if(state.config.bidMode==='open'){const eligible=state.players.filter(p=>p.connected!==false&&p.budget>0);state.auction={highBid:0,highBidder:null,passed:state.players.filter(p=>!eligible.includes(p)).map(p=>p.id),turn:eligible[0]?.id||null}}rememberCurrentSong()}
function rememberCurrentSong(){const item=state.items?.[state.round];if(!item?.name)return;const recent=JSON.parse(localStorage.getItem('draftDuelRecentSongs')||'[]'),key=`${item.name}|${item.sub||''}`.toLowerCase();localStorage.setItem('draftDuelRecentSongs',JSON.stringify([key,...recent.filter(x=>x!==key)].slice(0,60)))}
function current(){return state.items[state.round]} function player(id){return state.players.find(p=>p.id===id)}
function applyAction(id,action,value){if(state.result)return;const p=player(id);if(!p||p.connected===false)return;if(state.config.bidMode==='blind'){if(action!=='bid'||state.bids[id]!=null)return;const n=Number(value);if(!Number.isInteger(n)||n<0||n>p.budget)return;state.bids[id]=n;if(activePlayers().every(x=>state.bids[x.id]!=null))finishBlind()}else{const a=state.auction;if(a.turn!==id||a.passed.includes(id))return;if(action==='pass'){a.passed.push(id);advanceAuction()}else if(action==='bid'){const n=Number(value);if(!Number.isInteger(n)||n<=a.highBid||n>p.budget)return;a.highBid=n;a.highBidder=id;advanceAuction()}}broadcast();render()}
function activePlayers(){return state.players.filter(p=>p.connected!==false)}
function finishBlind(){const entries=activePlayers().map(p=>({p,b:state.bids[p.id]}));const max=Math.max(...entries.map(x=>x.b));const tied=entries.filter(x=>x.b===max);const ordered=[...state.players.slice(state.tieOffset),...state.players.slice(0,state.tieOffset)];const winner=ordered.find(p=>tied.some(x=>x.p.id===p.id));state.tieOffset=(state.players.indexOf(winner)+1)%state.players.length;award(winner,max,entries)}
function advanceAuction(){const a=state.auction,eligible=activePlayers().filter(p=>!a.passed.includes(p.id)&&p.budget>a.highBid);if(a.highBidder&&!a.passed.includes(a.highBidder)&&eligible.filter(p=>p.id!==a.highBidder).length===0)return award(player(a.highBidder),a.highBid,[]);if(!eligible.length){if(a.highBidder)return award(player(a.highBidder),a.highBid,[]);return award(null,0,[])}const start=state.players.findIndex(p=>p.id===a.turn);for(let n=1;n<=state.players.length;n++){const p=state.players[(start+n)%state.players.length];if(eligible.some(x=>x.id===p.id)&&p.id!==a.highBidder){a.turn=p.id;return}}if(a.highBidder)award(player(a.highBidder),a.highBid,[])}
function award(winner,amount,entries){if(winner){winner.budget-=amount;winner.picks.push({...current(),price:amount})}state.result={winner:winner?.id||null,amount,entries}}
function send(action,value){if(role==='guest'){if(action==='bid'){pendingBidRound=state.round;render()}set(ref(db,roomPath(currentRoomCode,`actions/${myId}`)),{action,value:value??null,nonce:crypto.randomUUID()}).catch(e=>{pendingBidRound=-1;render();alert(firebaseMessage(e))})}else applyAction(myId,action,value)}
function render(){if(!state)return;if(state.phase==='finished')return renderFinal();show('game');renderGameControls();if(state.paused){$('#actionCard').classList.remove('hidden');$('#resultsCard').classList.add('hidden');$('#actionCard').innerHTML='<div class="paused-state"><span>⏸</span><h2>Game paused</h2><p>The host will resume when everyone is ready.</p></div>';return}const item=current(),audio=$('#itemPreview');$('#roundLabel').textContent=`Round ${state.round+1} of ${state.config.rounds}`;$('#itemName').textContent=item.name;$('#itemSubtitle').textContent=item.sub||'';$('#itemArt').classList.toggle('hidden',!item.art);if(item.art)$('#itemArt').src=item.art;audio.classList.toggle('hidden',!item.preview);if(item.preview&&audio.src!==item.preview){audio.src=item.preview;audio.load()}if(!item.preview){audio.pause();audio.removeAttribute('src')}$('#scoreboard').innerHTML=state.players.map(p=>`<div class="score"><b>${esc(p.name)}</b><span>$${p.budget} left · ${p.picks.length} picks</span></div>`).join('');$('#actionCard').classList.toggle('hidden',Boolean(state.result));$('#resultsCard').classList.toggle('hidden',!state.result);if(state.result)return renderResult();state.config.bidMode==='blind'?renderBlind():renderAuction()}
function renderBlind(){const card=$('#actionCard'),submitted=new Set([...(state.bidStatus||[]),...Object.keys(state.bids||{})]);if(role==='guest'&&pendingBidRound===state.round)submitted.add(myId);const waiting=activePlayers().filter(p=>!submitted.has(p.id)),status=`<div class="waiting-panel"><b>${waiting.length?'Waiting for bids from':'All bids locked'}</b><div>${waiting.length?waiting.map(p=>`<span>${esc(p.name)}</span>`).join(''):'<span>Ready to reveal</span>'}</div></div>`;$('#scoreboard').innerHTML=state.players.map(p=>`<div class="score"><b>${esc(p.name)}</b><span>$${p.budget} left · ${submitted.has(p.id)?'Bid locked':'Choosing bid'}</span></div>`).join('');if(role==='local'){const p=state.players[state.localIndex];if(state.localStep==='handoff'){card.innerHTML=`<h3>Pass to ${esc(p.name)}</h3><p>Tap when only ${esc(p.name)} can see the screen.</p>${status}<button class="primary" id="ready">I’m ready</button>`;$('#ready').onclick=()=>{state.localStep='bid';render()}}else{card.innerHTML=bidForm(p,0,'Lock secret bid');bindBid(p.id,true)}}else{const p=player(myId),done=submitted.has(myId);card.innerHTML=done?`<h3>Bid locked</h3><p>Your amount is saved and remains secret.</p>${status}`:bidForm(p,0,'Lock secret bid');if(!done)bindBid(p.id,false)}}
function bidForm(p,min,label){return`<h3>${esc(p.name)}’s bid</h3><p>Available: $${p.budget}</p><div class="bidbox"><div><label>Choose your bid</label><div class="bid-stepper"><button id="bidMinus" type="button" aria-label="Decrease bid">−</button><output id="bidDisplay">$${min}</output><button id="bidPlus" type="button" aria-label="Increase bid">+</button><input id="bidValue" type="hidden" value="${min}"></div></div><button id="bidBtn">${label}</button></div><p id="bidError" class="error"></p>`}
function bindStepper(min,max){const input=$('#bidValue'),display=$('#bidDisplay'),minus=$('#bidMinus'),plus=$('#bidPlus');const update=n=>{n=Math.max(min,Math.min(max,n));input.value=n;display.textContent=`$${n}`;minus.disabled=n<=min;plus.disabled=n>=max};minus.onclick=()=>update(Number(input.value)-1);plus.onclick=()=>update(Number(input.value)+1);update(min)}
function bindBid(id,local){const p=player(id);bindStepper(0,p.budget);$('#bidBtn').onclick=()=>{const n=Number($('#bidValue').value);if(!Number.isInteger(n)||n<0||n>p.budget)return $('#bidError').textContent=`Enter a whole dollar amount from $0 to $${p.budget}.`;if(local){state.bids[id]=n;state.localIndex++;if(state.localIndex>=state.players.length)finishBlind();else state.localStep='handoff';render()}else send('bid',n)}}
function renderAuction(){const a=state.auction,turn=player(a.turn),high=a.highBidder?player(a.highBidder):null;$('#scoreboard').innerHTML=state.players.map(p=>`<div class="score ${p.id===a.turn?'turn':''}"><b>${esc(p.name)}</b><span>$${p.budget} left ${a.passed.includes(p.id)?'· Passed':''}</span></div>`).join('');const card=$('#actionCard');card.innerHTML=`<div class="auction"><p>Current bid</p><strong>$${a.highBid}</strong><p>${high?`by ${esc(high.name)}`:'No bids yet'}</p></div><div id="turnAction"></div>`;const act=$('#turnAction');if(role==='local'){const p=turn;act.innerHTML=`<h3>Pass to ${esc(p.name)}</h3><p>All auction activity is visible.</p><button id="localReady" class="primary">Take my turn</button>`;$('#localReady').onclick=()=>renderAuctionControls(p)}else if(myId===a.turn)renderAuctionControls(player(myId));else act.innerHTML=`<p class="muted">Waiting for ${esc(turn?.name||'the next player')}…</p>`}
function renderAuctionControls(p){const act=$('#turnAction'),min=state.auction.highBid+1;act.innerHTML=`<h3>${esc(p.name)}, your turn</h3>${bidForm(p,min,'Place bid')}<button id="passBtn">Pass for this item</button>`;bindStepper(min,p.budget);$('#bidBtn').onclick=()=>{const n=Number($('#bidValue').value);if(!Number.isInteger(n)||n<min||n>p.budget)return $('#bidError').textContent=`Bid a whole dollar amount from $${min} to $${p.budget}.`;if(role==='local')applyAction(p.id,'bid',n);else send('bid',n)};$('#passBtn').onclick=()=>role==='local'?applyAction(p.id,'pass'):send('pass')}
function renderResult(){const r=state.result,w=r.winner?player(r.winner):null,card=$('#resultsCard');$('#actionCard').classList.add('hidden');card.innerHTML=`<h3>${w?`<span class="winner">${esc(w.name)}</span> wins ${esc(current().name)} for $${r.amount}`:`No one drafted ${esc(current().name)}`}</h3>${r.entries?.length?'<div>'+r.entries.sort((a,b)=>b.b-a.b).map(x=>`<div class="result-row">${esc(x.p.name)} <b>$${x.b}</b></div>`).join('')+'</div>':''}${(role==='host'||role==='local')?'<button id="nextRound" class="primary">'+(state.round+1>=state.config.rounds?'See final lineups':'Next round')+'</button>':'<p class="muted">Waiting for the host…</p>'}`;const b=$('#nextRound');if(b)b.onclick=()=>{state.round++;$('#actionCard').classList.remove('hidden');if(state.round>=state.config.rounds)state.phase='finished';else beginRound();broadcast();render()}}
function renderFinal(){show('final');const winner=state.matchWinner?player(state.matchWinner):null,canChoose=role==='host'||role==='local';$('#finalResults').innerHTML=`${winner?`<div class="champion-banner celebration"><span>🏆</span><div><small>MATCH WINNER</small><h2>${winner.avatar?`${esc(winner.avatar)} `:''}${esc(winner.name)}</h2></div></div>`:canChoose?'<div class="winner-prompt"><h3>Who built the best lineup?</h3><p>Choose the match winner to save everyone’s result.</p></div>':'<p class="spectator-callout">Waiting for the host to choose the match winner…</p>'}<div class="final-lineups">${state.players.map(p=>`<article class="final-player ${p.id===state.matchWinner?'is-champion':''}"><h3>${p.avatar?`${esc(p.avatar)} `:''}${esc(p.name)} · $${p.budget} left</h3>${p.picks.length?p.picks.map(x=>`<p>${esc(x.name)} — $${x.price}</p>`).join(''):'<p class="muted">No picks</p>'}${!winner&&canChoose?`<button class="chooseWinner" data-player="${esc(p.id)}">Crown ${esc(p.name)}</button>`:''}</article>`).join('')}</div>${winner?`${gameHighlights()}<div class="share-result"><h3>Share the result</h3><p>Turn the final standings into a copyable party recap.</p><button id="shareResult" class="smallbtn">Share result card</button><span id="shareNotice"></span></div><div class="final-actions">${canChoose?'<button id="rematch" class="primary">Rematch</button>':'<span class="muted">The host can start a rematch.</span>'}<button id="partyNext">Party Hub</button><button id="newGame">Home</button></div>`:''}`;$$('.chooseWinner',$('#finalResults')).forEach(b=>b.onclick=()=>{state.matchWinner=b.dataset.player;if(role==='host')broadcast();renderFinal();recordCompletedGame()});const newGame=$('#newGame');if(newGame)newGame.onclick=()=>{clearSavedSession();location.href=urlFor('home').href};const partyNext=$('#partyNext');if(partyNext)partyNext.onclick=()=>navigate('party');const rematch=$('#rematch');if(rematch)rematch.onclick=()=>startRematch();const share=$('#shareResult');if(share)share.onclick=shareGameResult;if(winner){recordCompletedGame();announce(`${winner.name} wins Draft Duel`)}}
function gameHighlights(){const picks=state.players.flatMap(p=>(p.picks||[]).map(pick=>({player:p,...pick}))),big=picks.sort((a,b)=>(b.price||0)-(a.price||0))[0],bargain=[...picks].filter(x=>(x.price||0)>0).sort((a,b)=>a.price-b.price)[0],rich=[...state.players].sort((a,b)=>b.budget-a.budget)[0],collector=[...state.players].sort((a,b)=>b.picks.length-a.picks.length)[0];return`<section class="game-highlights"><p class="eyebrow">GAME HIGHLIGHTS</p><div>${big?`<article><span>💸</span><b>Biggest bid</b><small>${esc(big.player.name)} · ${esc(big.name)} for $${big.price}</small></article>`:''}${bargain?`<article><span>💎</span><b>Best bargain</b><small>${esc(bargain.player.name)} · ${esc(bargain.name)} for $${bargain.price}</small></article>`:''}<article><span>🏦</span><b>Budget boss</b><small>${esc(rich.name)} · $${rich.budget} left</small></article><article><span>🎒</span><b>Collector</b><small>${esc(collector.name)} · ${collector.picks.length} picks</small></article></div></section>`}
async function shareGameResult(){const winner=player(state.matchWinner),text=`🏆 ${winner?.name||'A player'} won Draft Duel!\n${state.players.map(p=>`${p.name}: ${p.picks.map(x=>x.name).join(', ')||'No picks'} · $${p.budget} left`).join('\n')}\n${location.origin}${location.pathname}`;try{if(navigator.share)await navigator.share({title:'Draft Duel results',text});else await navigator.clipboard.writeText(text);$('#shareNotice').textContent='Result ready to share!'}catch{$('#shareNotice').textContent='Sharing was cancelled.'}}
async function recordCompletedGame(){const user=auth.currentUser;if(!state?.matchWinner||!state.gameId||!user||user.isAnonymous||recordedGames.has(state.gameId)||!state.players.some(p=>p.id===user.uid))return;recordedGames.add(state.gameId);const me=state.players.find(p=>p.id===user.uid),won=state.matchWinner===user.uid,completedAt=Date.now(),mode=state.config.bidMode==='open'?'Open Auction':'Blind Bid';try{const result=await runTransaction(ref(db,`users/${user.uid}`),data=>{data??={};data.history??={};if(data.history[state.gameId])return data;data.stats??={games:0,wins:0,losses:0,itemsWon:0};data.stats.games=(data.stats.games||0)+1;data.stats.wins=(data.stats.wins||0)+(won?1:0);data.stats.losses=(data.stats.losses||0)+(won?0:1);data.stats.itemsWon=(data.stats.itemsWon||0)+(me.picks?.length||0);data.history[state.gameId]={completedAt,won,mode,players:state.players.map(p=>p.name),itemsWon:me.picks?.length||0};const keys=Object.keys(data.history).sort((a,b)=>(data.history[b].completedAt||0)-(data.history[a].completedAt||0));keys.slice(20).forEach(k=>delete data.history[k]);return data});currentAccountData=result.snapshot.val();const account=currentAccountData.account||{},username=account.username||accountName(user),avatar=account.avatar||avatarOptions[0];await set(ref(db,`publicProfiles/${user.uid}`),{username,avatar,stats:currentAccountData.stats||{},updatedAt:serverTimestamp()});renderCareer(currentAccountData.stats||{});renderHistory(currentAccountData.history||{})}catch(e){recordedGames.delete(state.gameId);console.warn('Could not save game history.',e)}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

// Phases 5–8: universal taste profiles, matchmaking, social play,
// reconnection, achievements, rematches, and installable-app polish.
function splitTaste(value){return[...new Set(String(value||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,20))]}
function renderTaste(){const taste=currentAccountData?.preferences||{};$('#tasteArtists').value=(taste.artists||[]).join(', ');$('#tasteGenres').value=(taste.genres||[]).join(', ')}
$('#tasteForm').onsubmit=async e=>{e.preventDefault();const user=auth.currentUser;if(!user||user.isAnonymous)return $('#tasteNotice').textContent='Sign in to save matchmaking preferences.';const preferences={artists:splitTaste($('#tasteArtists').value),genres:splitTaste($('#tasteGenres').value),updatedAt:Date.now()};try{await set(ref(db,`users/${user.uid}/preferences`),preferences);currentAccountData??={};currentAccountData.preferences=preferences;$('#tasteNotice').className='success';$('#tasteNotice').textContent='Music taste saved. You can now use matchmaking.'}catch(err){$('#tasteNotice').className='error';$('#tasteNotice').textContent=firebaseMessage(err)}};
function combinedTaste(){const manual=currentAccountData?.preferences||{},spotify=currentAccountData?.musicProfile||{};return{artists:[...new Set([...(manual.artists||[]),...(spotify.topArtists||[]).map(x=>x.name)].map(x=>x.toLowerCase()))].slice(0,30),genres:[...new Set([...(manual.genres||[]),...(spotify.topArtists||[]).flatMap(x=>x.genres||[])].map(x=>x.toLowerCase()))].slice(0,30),spotify:Boolean(spotify.spotifyId)}}
function compatibility(a,b){const aa=new Set(a.artists||[]),ag=new Set(a.genres||[]),sharedArtists=(b.artists||[]).filter(x=>aa.has(x)),sharedGenres=(b.genres||[]).filter(x=>ag.has(x));const total=Math.max(4,new Set([...(a.artists||[]),...(b.artists||[]),...(a.genres||[]),...(b.genres||[])]).size),score=Math.min(99,Math.round((sharedArtists.length*3+sharedGenres.length)*100/total));return{score,sharedArtists,sharedGenres}}
async function loadCommunity(){const user=await ensureAuth();if(!user||user.isAnonymous){$('#matchStatus').className='muted';$('#matchStatus').textContent='Sign in to use matchmaking and friends.';$('#matchSuggestions').innerHTML='';$('#friendRequests').innerHTML='';$('#friendsList').innerHTML='';$('#clubsList').innerHTML='<p class="muted">Sign in to create or join clubs.</p>';$('#rivalryList').innerHTML='';return loadLeaderboard()}renderRivalries();await Promise.all([renderMatchmaking(),loadFriends(),loadLeaderboard(),loadGameInvites(),loadClubs()])}
async function renderMatchmaking(){const user=auth.currentUser;if(!user||user.isAnonymous)return;const snap=await get(ref(db,'matchmaking')),entries=snap.val()||{},mine=entries[user.uid],taste=combinedTaste();$('#toggleMatchmaking').textContent=mine?'Leave matchmaking':'Join matchmaking';const ranked=Object.entries(entries).filter(([uid,x])=>uid!==user.uid&&Date.now()-(x.updatedAt||0)<3600000).map(([uid,x])=>({uid,...x,...compatibility(taste,x.taste||{})})).sort((a,b)=>b.score-a.score).slice(0,8);$('#matchStatus').className=mine?'success':'muted';$('#matchStatus').textContent=mine?`You’re visible to compatible players${taste.spotify?' with Spotify-enhanced matching':', using your saved preferences'}.`:'Join the queue to appear to other players.';$('#matchSuggestions').innerHTML=ranked.length?`<h4>Compatible players</h4>${ranked.map(x=>`<article class="match-row"><span class="match-score">${x.score}%</span><div><b>${esc(x.avatar||'🎵')} ${esc(x.name||'Player')}</b><small>${x.sharedArtists.length?`Both like ${esc(x.sharedArtists.slice(0,3).join(', '))}`:x.sharedGenres.length?`Shared genres: ${esc(x.sharedGenres.slice(0,3).join(', '))}`:'Ready for a fresh matchup'}</small></div><button class="challengePlayer smallbtn" data-uid="${esc(x.uid)}">Challenge</button></article>`).join('')}`:'<p class="muted">No other players are in the queue yet. Invite a friend to join matchmaking.</p>';$$('.challengePlayer',$('#matchSuggestions')).forEach(button=>button.onclick=()=>prepareChallenge(button.dataset.uid,entries[button.dataset.uid]))}
$('#toggleMatchmaking').onclick=async()=>{const user=auth.currentUser;if(!user||user.isAnonymous){navigate('account');return}const own=ref(db,`matchmaking/${user.uid}`),snap=await get(own);if(snap.exists())await remove(own);else{const taste=combinedTaste();if(!taste.artists.length&&!taste.genres.length){navigate('account');$('#tasteNotice').textContent='Add at least one artist or genre before joining matchmaking.';return}const name=currentAccountData?.account?.username||accountName(user),avatar=currentAccountData?.account?.avatar||'🎵';await set(own,{name,avatar,taste,updatedAt:Date.now()});await onDisconnect(own).remove()}renderMatchmaking().catch(()=>{})};
function prepareChallenge(uid,entry){pendingChallengeTarget=uid;navigate('host');const root=$('#hostForm .setup');const mine=combinedTaste(),theirs=entry?.taste||{},shared=(theirs.artists||[]).filter(x=>mine.artists.includes(x)).slice(0,4);if(shared.length){const box=root.querySelector('.artists');box.innerHTML='';shared.forEach(x=>addArtist(box,x.replace(/\b\w/g,c=>c.toUpperCase())))}$('#hostName').focus()}
async function loadGameInvites(){const user=auth.currentUser;if(!user||user.isAnonymous)return;const snap=await get(ref(db,`gameInvites/${user.uid}`)),invites=Object.entries(snap.val()||{}).filter(([,x])=>x.room&&Date.now()-(x.createdAt||0)<86400000);if(!invites.length)return;$('#matchSuggestions').insertAdjacentHTML('afterbegin',`<div class="invite-stack"><h4>Game invitations</h4>${invites.map(([uid,x])=>`<article><b>${esc(x.fromName||'A player')} challenged you</b><button class="acceptInvite smallbtn" data-from="${esc(uid)}" data-room="${esc(x.room)}">Join ${esc(x.room)}</button></article>`).join('')}</div>`);$$('.acceptInvite',$('#matchSuggestions')).forEach(b=>b.onclick=async()=>{await remove(ref(db,`gameInvites/${user.uid}/${b.dataset.from}`));$('#joinCode').value=b.dataset.room;$('#joinName').value=currentAccountData?.account?.username||accountName(user);navigate('join')})}
$('#friendSearchForm').onsubmit=async e=>{e.preventDefault();const user=auth.currentUser,query=$('#friendSearch').value.trim().toLowerCase();if(!user||user.isAnonymous)return navigate('account');try{const snap=await get(ref(db,'publicProfiles')),match=Object.entries(snap.val()||{}).find(([uid,p])=>uid!==user.uid&&String(p.username||'').toLowerCase()===query);if(!match)throw Error('No player has that exact username.');const [target]=match;await set(ref(db,`friendRequests/${target}/${user.uid}`),{fromUid:user.uid,name:currentAccountData?.account?.username||accountName(user),avatar:currentAccountData?.account?.avatar||'🎵',createdAt:Date.now()});$('#friendNotice').className='success';$('#friendNotice').textContent='Friend request sent.'}catch(err){$('#friendNotice').className='error';$('#friendNotice').textContent=err.message}};
async function loadFriends(){const user=auth.currentUser;if(!user||user.isAnonymous)return;const [requestSnap,friendSnap]=await Promise.all([get(ref(db,`friendRequests/${user.uid}`)),get(ref(db,`friends/${user.uid}`))]),requests=requestSnap.val()||{},friends=friendSnap.val()||{};$('#friendRequests').innerHTML=Object.keys(requests).length?`<h4>Requests</h4>${Object.entries(requests).map(([uid,x])=>`<article class="friend-row"><span>${esc(x.avatar||'🎵')} <b>${esc(x.name||'Player')}</b></span><button class="acceptFriend smallbtn" data-uid="${esc(uid)}">Accept</button></article>`).join('')}`:'';$('#friendsList').innerHTML=`<h4>Friends</h4>${Object.entries(friends).length?Object.entries(friends).map(([uid,x])=>`<article class="friend-row"><span>${esc(x.avatar||'🎵')} <b>${esc(x.name||'Player')}</b></span><button class="friendChallenge smallbtn" data-uid="${esc(uid)}">Challenge</button></article>`).join(''):'<p class="muted">Add friends by their exact username.</p>'}`;$$('.acceptFriend',$('#friendRequests')).forEach(b=>b.onclick=async()=>{const request=requests[b.dataset.uid],me={name:currentAccountData?.account?.username||accountName(user),avatar:currentAccountData?.account?.avatar||'🎵',since:Date.now()};await set(ref(db,`friends/${b.dataset.uid}/${user.uid}`),me);await set(ref(db,`friends/${user.uid}/${b.dataset.uid}`),{name:request.name,avatar:request.avatar||'🎵',since:Date.now()});await remove(ref(db,`friendRequests/${user.uid}/${b.dataset.uid}`));loadFriends()});$$('.friendChallenge',$('#friendsList')).forEach(b=>b.onclick=()=>prepareChallenge(b.dataset.uid,{taste:{}}))}
async function loadLeaderboard(){try{const snap=await get(ref(db,'publicProfiles')),players=Object.entries(snap.val()||{}).map(([uid,p])=>({uid,...p,games:p.stats?.games||0,wins:p.stats?.wins||0})).sort((a,b)=>b.wins-a.wins||(b.games?b.wins/b.games:0)-(a.games?a.wins/a.games:0)).slice(0,25);$('#leaderboard').innerHTML=players.length?players.map((p,i)=>`<article class="leader-row"><span class="rank">${i+1}</span><span class="leader-avatar">${esc(p.avatar||'🎵')}</span><div><b>${esc(p.username||'Draft player')}</b><small>${p.games} games · ${p.games?Math.round(p.wins/p.games*100):0}% win rate</small></div><strong>${p.wins} wins</strong></article>`).join(''):'<p class="muted">No ranked players yet.</p>'}catch{$('#leaderboard').innerHTML='<p class="error">Publish the newest Firebase rules to load the leaderboard.</p>'}}
$('#refreshCommunity').onclick=()=>loadCommunity();
$('#clubForm').onsubmit=async e=>{e.preventDefault();const user=auth.currentUser,name=$('#clubName').value.trim();if(!user||user.isAnonymous)return navigate('account');if(name.length<2)return;const code=Math.random().toString(36).slice(2,8).toUpperCase(),member={name:currentAccountData?.account?.username||accountName(user),avatar:currentAccountData?.account?.avatar||'🎵',joinedAt:Date.now()};try{await set(ref(db,`clubs/${code}`),{ownerUid:user.uid,name,createdAt:Date.now(),members:{[user.uid]:member}});$('#clubNotice').className='success';$('#clubNotice').textContent=`Club created. Share code ${code}.`;loadClubs()}catch(err){$('#clubNotice').className='error';$('#clubNotice').textContent=firebaseMessage(err)}};
$('#joinClubForm').onsubmit=async e=>{e.preventDefault();const user=auth.currentUser,code=$('#clubCode').value.trim().toUpperCase();if(!user||user.isAnonymous)return navigate('account');try{const snap=await get(ref(db,`clubs/${code}`));if(!snap.exists())throw Error('Club not found.');await set(ref(db,`clubs/${code}/members/${user.uid}`),{name:currentAccountData?.account?.username||accountName(user),avatar:currentAccountData?.account?.avatar||'🎵',joinedAt:Date.now()});$('#clubNotice').className='success';$('#clubNotice').textContent=`Joined ${snap.val().name}.`;loadClubs()}catch(err){$('#clubNotice').className='error';$('#clubNotice').textContent=err.message}};
async function loadClubs(){const user=auth.currentUser;if(!user||user.isAnonymous)return;const [clubSnap,profilesSnap]=await Promise.all([get(ref(db,'clubs')),get(ref(db,'publicProfiles'))]),profiles=profilesSnap.val()||{},clubs=Object.entries(clubSnap.val()||{}).filter(([,club])=>club.members?.[user.uid]);$('#clubsList').innerHTML=clubs.length?clubs.map(([code,club])=>{const members=Object.keys(club.members||{}).map(uid=>({uid,...club.members[uid],wins:profiles[uid]?.stats?.wins||0})).sort((a,b)=>b.wins-a.wins);return`<article class="club-card"><div><b>${esc(club.name)}</b><code>${esc(code)}</code></div>${members.map((member,index)=>`<p><span>${index+1}. ${esc(member.avatar||'🎵')} ${esc(member.name)}</span><strong>${member.wins} wins</strong></p>`).join('')}</article>`}).join(''):'<p class="muted">No clubs yet.</p>'}
function renderRivalries(){const me=currentAccountData?.account?.username||auth.currentUser?.displayName||'',games=Object.values(currentAccountData?.history||{}),rivals={};games.forEach(game=>(game.players||[]).filter(name=>name!==me).forEach(name=>{rivals[name]??={games:0,wins:0};rivals[name].games++;if(game.won)rivals[name].wins++}));const rows=Object.entries(rivals).sort((a,b)=>b[1].games-a[1].games).slice(0,6);$('#rivalryList').innerHTML=rows.length?rows.map(([name,record])=>`<article class="rival-row"><span>⚔️ <b>${esc(name)}</b></span><small>${record.wins}–${record.games-record.wins} across ${record.games} games</small></article>`).join(''):'<p class="muted">Complete games with signed-in friends to start a rivalry.</p>'}
function renderAchievements(stats){const achievements=[['First Draft',(stats.games||0)>=1,'Complete a game'],['Auction Ace',(stats.wins||0)>=1,'Win your first duel'],['Collector',(stats.itemsWon||0)>=10,'Draft 10 items'],['Veteran',(stats.games||0)>=10,'Play 10 games'],['Champion',(stats.wins||0)>=10,'Win 10 games']];$('#achievementList').innerHTML='<h4>Achievements</h4>'+achievements.map(([name,unlocked,hint])=>`<span class="achievement ${unlocked?'unlocked':''}" title="${esc(hint)}">${unlocked?'✓':'○'} ${esc(name)}</span>`).join('')}
function sessionKey(){return'draftDuelActiveSession'}
function saveOnlineSession(savedRole,code,name){localStorage.setItem(sessionKey(),JSON.stringify({role:savedRole,code,name,uid:auth.currentUser?.uid,updatedAt:Date.now()}))}
function clearSavedSession(){localStorage.removeItem(sessionKey())}
async function resumeOnlineSession(){const saved=JSON.parse(localStorage.getItem(sessionKey())||'null'),user=auth.currentUser;if(!saved||!user||saved.uid!==user.uid||Date.now()-saved.updatedAt>86400000)return;const roomSnap=await get(ref(db,roomPath(saved.code)));if(!roomSnap.exists()){clearSavedSession();return}const room=roomSnap.val();currentRoomCode=saved.code;myId=user.uid;onlineHostUid=room.hostUid;state=hydrateState(room.state);await set(ref(db,roomPath(saved.code,`members/${myId}`)),true);if(room.hostUid===user.uid){role='host';await set(ref(db,roomPath(saved.code,`presence/${myId}`)),{online:true});await onDisconnect(ref(db,roomPath(saved.code,`presence/${myId}`))).remove();attachHost(saved.code)}else if(state.players.some(p=>p.id===user.uid)){role='guest';await set(ref(db,roomPath(saved.code,`presence/${myId}`)),{online:true});await onDisconnect(ref(db,roomPath(saved.code,`presence/${myId}`))).remove();clearOnlineListeners();onlineUnsubs.push(onValue(ref(db,roomPath(saved.code,'state')),snap=>{if(!snap.exists()){clearSavedSession();return}state=hydrateState(snap.val());state.phase==='lobby'?renderLobby():render()}));watchHostMigration(saved.code,onlineHostUid)}else{clearSavedSession();return}attachRoomSocial(saved.code);state.phase==='lobby'?renderLobby():render()}
function watchHostMigration(code,hostUid){onlineUnsubs.push(onValue(ref(db,roomPath(code,`presence/${hostUid}`)),snap=>{clearTimeout(hostMigrationTimer);if(snap.exists()||role!=='guest')return;hostMigrationTimer=setTimeout(()=>claimHost(code,hostUid),10000)}))}
async function claimHost(code,expectedHost){if(role!=='guest'||!state?.players.some(p=>p.id===myId))return;try{const result=await runTransaction(ref(db,roomPath(code)),room=>{if(!room||room.hostUid!==expectedHost||room.presence?.[expectedHost]||room.members?.[myId]!==true)return;room.hostUid=myId;return room});if(!result.committed||result.snapshot.val()?.hostUid!==myId)return;role='host';onlineHostUid=myId;await set(ref(db,roomPath(code,`presence/${myId}`)),{online:true});await onDisconnect(ref(db,roomPath(code,`presence/${myId}`))).remove();attachHost(code);attachRoomSocial(code);saveOnlineSession('host',code,player(myId)?.name||'Host');await broadcast();state.phase==='lobby'?renderLobby():render()}catch(e){console.info('Host migration was not available.',e)}}
async function startRematch(){if(role==='guest')return;if(role==='local'){const names=state.players.map(p=>p.name),items=shuffle(state.items);state=fresh(state.config,names,items);localNames=state.players.map(x=>x.id);beginRound();render();return}if(role==='host'){const old=state,items=shuffle(old.items),players=old.players.map(p=>({id:p.id,name:p.name,avatar:p.avatar||'',budget:old.config.budget,picks:[],connected:p.connected!==false}));state=fresh(old.config,[],items);state.players=players;state.phase='lobby';await broadcast();renderLobby()}}

const arcadeModeIds=['snake','salary','teams','mystery','lightning','album','aux','name-song','timeline','beat-tap','impostor','festival','playlist-prompt','sabotage','songless','songless-daily','reverse-audio','one-second','album-puzzle','higher-lower','music-bingo','fake-track','rhythm-copycat','tempo-guess','reaction-race','caption-clash','quick-draw','word-chain','majority-rules','auction-trivia','power-draft','draft-royale'];
const roomMessages=[];const seenRoomMessages=new Set();
function attachRoomSocial(code){onlineUnsubs.push(onChildAdded(ref(db,roomPath(code,'chat')),snap=>{if(seenRoomMessages.has(snap.key))return;seenRoomMessages.add(snap.key);const message=snap.val()||{};if(message.type==='reaction')showReaction(message);else{roomMessages.push(message);roomMessages.splice(0,Math.max(0,roomMessages.length-30));renderRoomMessages()}}));onlineUnsubs.push(onValue(ref(db,roomPath(code,'poolSuggestions')),snap=>renderPoolSuggestions(snap.val()||{})))}
function renderRoomMessages(){if(!$('#chatMessages'))return;$('#chatMessages').innerHTML=roomMessages.length?roomMessages.map(message=>`<p><b>${esc(message.name||'Player')}</b><span>${esc(message.text||'')}</span></p>`).join(''):'<p class="muted">Room chat is ready.</p>';$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}
function roomDisplayName(){return player(myId)?.name||currentAccountData?.account?.username||auth.currentUser?.displayName||'Player'}
async function sendRoomMessage(payload){if(!currentRoomCode||!myId||role==='local')return;await push(ref(db,roomPath(currentRoomCode,'chat')),{uid:myId,name:roomDisplayName(),createdAt:serverTimestamp(),...payload}).catch(()=>{})}
$('#chatForm').onsubmit=e=>{e.preventDefault();const text=$('#chatInput').value.trim();if(!text)return;sendRoomMessage({type:'message',text});$('#chatInput').value=''};
$('#poolSuggestionForm').onsubmit=async e=>{e.preventDefault();const text=$('#poolSuggestionInput').value.trim();if(!text||!currentRoomCode||role==='local')return;await set(ref(db,roomPath(currentRoomCode,`poolSuggestions/${myId}`)),{text,name:roomDisplayName(),createdAt:serverTimestamp()}).catch(()=>{});$('#poolSuggestionInput').value=''};
function renderPoolSuggestions(suggestions){$('#poolSuggestions').innerHTML=Object.entries(suggestions).map(([uid,item])=>`<span>${esc(item.text)} <small>by ${esc(item.name)}</small>${role==='host'?`<button class="acceptPoolSuggestion" data-uid="${esc(uid)}">Add</button>`:''}</span>`).join('');$$('.acceptPoolSuggestion',$('#poolSuggestions')).forEach(button=>button.onclick=async()=>{const item=suggestions[button.dataset.uid],parts=item.text.split(/\s+[—|-]\s+/),song={name:parts[0],sub:parts.slice(1).join(' — ')||`Suggested by ${item.name}`};state.items.splice(Math.floor(Math.random()*Math.max(1,state.items.length)),0,song);state.items=state.items.slice(0,state.config.rounds);await remove(ref(db,roomPath(currentRoomCode,`poolSuggestions/${button.dataset.uid}`)));broadcast();renderLobby()})}
$$('[data-reaction]').forEach(button=>button.onclick=()=>sendRoomMessage({type:'reaction',emoji:button.dataset.reaction}));
function showReaction(message){const target=!$('#game').classList.contains('hidden')?$('#reactionOverlay'):document.body,bubble=document.createElement('span');bubble.className='reaction-bubble';bubble.textContent=`${message.emoji||'🎵'} ${message.name||''}`;target.append(bubble);setTimeout(()=>bubble.remove(),2600)}
function renderAudienceVoting(code,s,votes){const counts=Object.values(votes).reduce((result,playerId)=>(result[playerId]=(result[playerId]||0)+1,result),{}),section=document.createElement('section');section.className='audience-vote';section.innerHTML=`<p class="eyebrow">AUDIENCE CHOICE</p><h3>Who built the best lineup?</h3><div>${s.players.map(player=>`<button class="audienceVoteButton" data-player="${esc(player.id)}"><b>${esc(player.name)}</b><span>${counts[player.id]||0} votes</span></button>`).join('')}</div><p id="audienceVoteNotice"></p>`;$('#spectatorContent').append(section);$$('.audienceVoteButton',section).forEach(button=>button.onclick=async()=>{const user=await ensureAuth();await set(ref(db,`publicGames/${code}/votes/${user.uid}`),button.dataset.player);$('#audienceVoteNotice').className='success';$('#audienceVoteNotice').textContent='Your audience vote is locked in.'})}
function renderGameControls(){const controls=$('#hostGameControls');controls.classList.toggle('hidden',role!=='host');if(role!=='host')return;controls.innerHTML=`<button id="pauseGame" class="smallbtn">${state.paused?'Resume':'Pause'}</button><button id="skipItem" class="smallbtn">Skip item</button><button id="fullScreenGame" class="smallbtn">Full screen</button>`;$('#pauseGame').onclick=()=>{state.paused=!state.paused;broadcast();render()};$('#skipItem').onclick=()=>{if(!state.result)award(null,0,[]);broadcast();render()};$('#fullScreenGame').onclick=()=>document.documentElement.requestFullscreen?.()}
async function loadPartyHub(){
  ensurePartyExtras();renderDailyChallenge();renderPartyProgress();restorePartySettings();
  try{await ensureAuth();if(partyDirectoryUnsub)partyDirectoryUnsub();partyDirectoryUnsub=onValue(ref(db,'publicGames'),snap=>renderPublicLobbies(snap.val()||{}),()=>{$('#publicLobbyList').innerHTML='<p class="error">Publish the latest Firebase rules to browse public rooms.</p>'})}catch(e){$('#publicLobbyList').innerHTML=`<p class="error">${esc(firebaseMessage(e))}</p>`}
}
function ensurePartyExtras(){
  if(!$('#previewVolume')){
    const stylePanel=[...$$('.party-panel')].find(panel=>panel.querySelector('h3')?.textContent==='Party Style');
    stylePanel?.insertAdjacentHTML('beforeend',`<label>Preview volume<input id="previewVolume" type="range" min="0" max="100" step="5" value="${esc(localStorage.getItem('draftDuelPreviewVolume')||'70')}"></label><button id="enableNotifications" class="smallbtn" type="button">Enable invite alerts</button><p id="notificationNotice" class="muted"></p>`);
    $('#previewVolume').oninput=e=>localStorage.setItem('draftDuelPreviewVolume',e.target.value);
    $('#enableNotifications').onclick=async()=>{if(!('Notification'in window))return $('#notificationNotice').textContent='Notifications are not supported in this browser.';const permission=await Notification.requestPermission();$('#notificationNotice').className=permission==='granted'?'success':'muted';$('#notificationNotice').textContent=permission==='granted'?'Invite alerts are enabled.':'Notification permission was not enabled.'};
  }
  if(!$('#smartPartyPlanner')){
    const grid=$('.party-grid');
    grid?.insertAdjacentHTML('beforeend',`<section id="smartPartyPlanner" class="party-panel"><span class="party-icon">✨</span><h3>Smart Party Planner</h3><p>Get a quick recommendation for your group.</p><div class="two"><label>Players<input id="plannerPlayers" type="number" min="2" max="8" value="4"></label><label>Time<select id="plannerTime"><option value="10">10 min</option><option value="25" selected>25 min</option><option value="45">45+ min</option></select></label></div><button id="planParty" class="smallbtn" type="button">Suggest a game</button><div id="plannerResult"></div></section>`);
    $('#planParty').onclick=()=>{const players=Math.max(2,Math.min(8,Number($('#plannerPlayers').value)||4)),minutes=Number($('#plannerTime').value),choice=minutes<=10?{name:'Lightning Auction',mode:'lightning',why:'fast turns and instant scores'}:players>=6?{name:'Music Impostor',mode:'impostor',why:'best with a lively larger group'}:minutes>=45?{name:'Party Tournament',mode:'snake',why:'enough time for a multi-round competition'}:{name:'Name That Song',mode:'name-song',why:'easy to learn and great for mixed music tastes'};$('#plannerResult').innerHTML=`<div class="roulette-pick"><span>🎧</span><b>${choice.name}</b><small>${choice.why}</small><button id="playPlannedGame" class="smallbtn">Play</button></div>`;$('#playPlannedGame').onclick=()=>location.href=urlFor('arcade').href+`&mode=${choice.mode}`};
  }
}
document.addEventListener('play',event=>{if(event.target instanceof HTMLAudioElement)event.target.volume=Math.max(0,Math.min(1,Number(localStorage.getItem('draftDuelPreviewVolume')||70)/100))},true);
function renderPublicLobbies(data){
  const mode=$('#publicModeFilter').value,status=$('#publicStatusFilter').value,now=Date.now();
  const games=Object.entries(data).filter(([,game])=>game.state?.config?.visibility==='public'&&game.state?.phase!=='finished'&&now-(game.updatedAt||0)<86400000).filter(([,game])=>mode==='all'||game.state.config?.bidMode===mode).filter(([,game])=>status==='all'||(status==='lobby'?game.state.phase==='lobby':game.state.phase==='playing')).sort((a,b)=>(b[1].updatedAt||0)-(a[1].updatedAt||0));
  $('#publicLobbyList').innerHTML=games.length?games.map(([code,game])=>{const s=hydrateState(game.state),joinable=s.phase==='lobby'&&s.players.length<8,watchable=s.config?.spectators!=='off',host=s.players[0]?.name||'Host';return`<article class="public-room"><div><span class="live-dot">${s.phase==='lobby'?'OPEN':'LIVE'}</span><h4>${esc(host)}’s room</h4><p>${s.players.length}/8 players · ${s.config?.bidMode==='open'?'Open Auction':'Blind Bid'} · ${s.config?.rounds||5} rounds</p><small>Room ${esc(code)}${s.config?.artists?.length?` · ${s.config.artists.map(a=>esc(a.name||a)).slice(0,3).join(', ')}`:''}</small></div><button class="${joinable?'joinPublic':watchable?'watchPublic':''} smallbtn" data-room="${esc(code)}" ${!joinable&&!watchable?'disabled':''}>${joinable?'Join game':watchable?'Watch':'Spectators off'}</button></article>`}).join(''):'<div class="empty-live"><h3>No matching public rooms</h3><p>Be the first to host one, or change the filters.</p></div>';
  $$('.joinPublic',$('#publicLobbyList')).forEach(button=>button.onclick=()=>{$('#joinCode').value=button.dataset.room;$('#joinName').value=currentAccountData?.account?.username||auth.currentUser?.displayName||'';navigate('join')});
  $$('.watchPublic',$('#publicLobbyList')).forEach(button=>button.onclick=()=>watchGame(button.dataset.room));
}
$('#refreshPublicGames').onclick=()=>loadPartyHub();$('#publicModeFilter').onchange=()=>loadPartyHub();$('#publicStatusFilter').onchange=()=>loadPartyHub();
$('#spinMode').onclick=()=>{const id=arcadeModeIds[Math.floor(Math.random()*arcadeModeIds.length)],labels={'name-song':'Name That Song','beat-tap':'Beat Tap','playlist-prompt':'Playlist Prompt'};$('#rouletteResult').innerHTML=`<div class="roulette-pick"><span>🎉</span><b>${esc(labels[id]||id.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase()))}</b><button id="playRoulette" class="smallbtn">Play it</button></div>`;announce(`Tonight's game is ${labels[id]||id.replace(/-/g,' ')}`);$('#playRoulette').onclick=()=>location.href=urlFor('arcade').href+`&mode=${id}`};
function renderDailyChallenge(){const day=new Date().toISOString().slice(0,10),seed=[...day].reduce((n,c)=>n+c.charCodeAt(0),0),challenges=[['One-Artist Wonder','Play a five-round draft using just one artist.'],['Perfect Pulse','Score 75% or higher in Beat Tap.'],['Budget Hero','Finish Salary Cap with at least $8 remaining.'],['Secret Selector','Win one Aux Battle prompt.'],['Time Traveller','Answer three Music Timeline questions correctly.'],['Impostor Hunter','Catch the Music Impostor.']],[name,description]=challenges[seed%challenges.length];$('#dailyChallenge').innerHTML=`<b>${esc(name)}</b><p>${esc(description)}</p><small>Refreshes tomorrow · ${day}</small>`}
$('#createTournament').onclick=()=>{$('#tournamentBuilder').innerHTML=`<label>Players<input id="tournamentNames" placeholder="Alex, Sam, Jordan"></label><label>Games<select id="tournamentLength"><option value="3">Quick · 3 games</option><option value="5">Party · 5 games</option><option value="7">Championship · 7 games</option></select></label><button id="saveTournament" class="smallbtn">Create playlist</button>`;$('#saveTournament').onclick=()=>{const count=Number($('#tournamentLength').value),players=$('#tournamentNames').value.split(',').map(x=>x.trim()).filter(Boolean),games=shuffle(arcadeModeIds).slice(0,count),tournament={players,games,scores:Object.fromEntries(players.map(p=>[p,0])),createdAt:Date.now()};localStorage.setItem('draftDuelTournament',JSON.stringify(tournament));renderTournament(tournament)}};
function renderTournament(tournament=JSON.parse(localStorage.getItem('draftDuelTournament')||'null')){if(!tournament)return;$('#tournamentBuilder').innerHTML=`<div class="tournament-list">${tournament.games.map((game,index)=>`<button class="tournamentGame" data-mode="${game}"><span>${index+1}</span>${esc(game.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase()))}</button>`).join('')}</div><p>${tournament.players.length?`Players: ${tournament.players.map(esc).join(', ')}`:'Add players when each game begins.'}</p>`;$$('.tournamentGame',$('#tournamentBuilder')).forEach(button=>button.onclick=()=>location.href=urlFor('arcade').href+`&mode=${button.dataset.mode}`)}
function restorePartySettings(){const theme=localStorage.getItem('draftDuelTheme')||'paper';document.body.dataset.theme=theme;$('#themeSelect').value=theme;$('#announcerToggle').checked=localStorage.getItem('draftDuelAnnouncer')==='on';$('#partyLibrary').value=localStorage.getItem('draftDuelPartyLibrary')||'';renderTournament()}
$('#themeSelect').onchange=e=>{document.body.dataset.theme=e.target.value;localStorage.setItem('draftDuelTheme',e.target.value)};$('#announcerToggle').onchange=e=>localStorage.setItem('draftDuelAnnouncer',e.target.checked?'on':'off');
function announce(message){if(localStorage.getItem('draftDuelAnnouncer')==='on'&&'speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(message))}}
$('#saveLibrary').onclick=()=>{localStorage.setItem('draftDuelPartyLibrary',$('#partyLibrary').value.trim());$('#libraryNotice').className='success';$('#libraryNotice').textContent='Party library saved.'};
function renderPartyProgress(){const records=Object.values(JSON.parse(localStorage.getItem('draftDuelArcadeRecords')||'{}')),games=records.reduce((sum,x)=>sum+(x.games||0),0),wins=records.reduce((sum,x)=>sum+(x.wins||0),0),xp=games*50+wins*100,level=Math.floor(xp/500)+1;$('#partyProgress').innerHTML=`<div class="level-ring"><strong>${level}</strong><small>LEVEL</small></div><p>${xp} XP · ${games} Arcade games · ${wins} wins</p><div class="quest"><b>Weekly quest</b><span>${Math.min(games,5)}/5 games played</span><progress max="5" value="${Math.min(games,5)}"></progress></div>`}
$('#savePreset').onclick=()=>{const root=$('#hostForm .setup'),preset={bidMode:root.querySelector('.bidMode').value,budget:root.querySelector('.budget').value,rounds:root.querySelector('.rounds').value,source:root.querySelector('.source').value,artists:$$('.artist',root).map(x=>window.ArtistPicker.get(x)),visibility:$('#roomVisibility').value,spectators:$('#spectatorAccess').value};localStorage.setItem('draftDuelHostPreset',JSON.stringify(preset));$('#savePreset').textContent='Saved ✓';setTimeout(()=>$('#savePreset').textContent='Save setup',1500)};
$('#loadPreset').onclick=()=>{const preset=JSON.parse(localStorage.getItem('draftDuelHostPreset')||'null');if(!preset)return;const root=$('#hostForm .setup');root.querySelector('.bidMode').value=preset.bidMode||'blind';root.querySelector('.budget').value=preset.budget||20;root.querySelector('.rounds').value=preset.rounds||5;root.querySelector('.source').value=preset.source||'artist';$('#roomVisibility').value=preset.visibility||'public';$('#spectatorAccess').value=preset.spectators||'on';const box=root.querySelector('.artists');box.innerHTML='';(preset.artists?.length?preset.artists:[{name:'Bruno Mars',id:''}]).forEach(artist=>addArtist(box,artist));root.querySelector('.source').dispatchEvent(new Event('change'))};
addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installApp').classList.remove('hidden')});
$('#installApp').onclick=async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('#installApp').classList.add('hidden')};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
